var DEFAULT_CHAR_WIDTH_10PX = 6;
var CJK_CHAR_WIDTH_10PX = 10.2;
var HALFWIDTH_KANA_WIDTH_10PX = 5.5;
function isCjkCharacter(char) {
  const code = char.codePointAt(0);
  if (!code) return false;
  return (
    // CJK Radicals, Symbols, Punctuation, Japanese Hiragana & Katakana
    code >= 11904 && code <= 13311 || // CJK Unified Ideographs & Extension A
    code >= 13312 && code <= 19903 || code >= 19968 && code <= 40959 || // Hangul (Korean)
    code >= 44032 && code <= 55215 || // CJK Compatibility Ideographs & Forms
    code >= 63744 && code <= 64255 || // Fullwidth ASCII variants, Fullwidth punctuation (！, ？, ：, etc.)
    code >= 65281 && code <= 65376 || // Fullwidth currency & symbols (￥, ￠, etc.)
    code >= 65504 && code <= 65510 || // Extension B..F
    code >= 131072 && code <= 195103
  );
}
function getCharacterWidth10px(char) {
  if (char in CHAR_WIDTHS_10PX) {
    return CHAR_WIDTHS_10PX[char];
  }
  const code = char.codePointAt(0);
  if (code && code >= 65377 && code <= 65439) {
    return HALFWIDTH_KANA_WIDTH_10PX;
  }
  if (isCjkCharacter(char)) {
    return CJK_CHAR_WIDTH_10PX;
  }
  return DEFAULT_CHAR_WIDTH_10PX;
}
function measureText(text, fontSize = 11.5, isBold = true, letterSpacing = 0.3) {
  if (!text) return 0;
  const scale = fontSize / 10;
  const boldMultiplier = isBold ? 1.08 : 1;
  let width = 0;
  for (const char of text) {
    const baseWidth = getCharacterWidth10px(char);
    width += baseWidth * scale * boldMultiplier + letterSpacing;
  }
  return Math.ceil(width);
}

// src/generator.ts
var DEFAULT_FONT_FAMILY = "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Hiragino Sans', 'Hiragino Kaku Gothic ProN', 'Yu Gothic', Meiryo, 'Microsoft YaHei', 'PingFang SC', 'Noto Sans CJK SC', 'Noto Sans CJK JP', sans-serif";
function resolveRadius(radius, height) {
  if (typeof radius === "number") return radius;
  if (radius === "sharp") return 0;
  if (radius === "pill") return Math.floor(height / 2);
  return height >= 32 ? 8 : 6;
}
function resolveIconPath(icon) {
  if (!icon) return null;
  if (icon in ICONS) {
    return ICONS[icon] ?? null;
  }
  if (icon.trim().startsWith("M") || icon.trim().startsWith("m")) {
    return icon;
  }
  return null;
}
function escapeXml(unsafe) {
  return unsafe.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&apos;");
}
function generateBadge(options) {
  const {
    value,
    label,
    color = PALETTE.electricBlue,
    leftColor = PALETTE.slateDark,
    textColor,
    labelColor,
    icon,
    iconColor,
    iconViewBox = "0 0 24 24",
    style = "solid",
    height = 28,
    radius,
    letterSpacing = 0.3,
    ariaLabel,
    autoContrast = true
  } = options;
  const rx = resolveRadius(radius, height);
  const iconPath = resolveIconPath(icon);
  const fontSize = height <= 24 ? 10 : height >= 32 ? 13 : 11.5;
  const labelFontSize = height <= 24 ? 9.5 : height >= 32 ? 12 : 11;
  const iconSize = height <= 24 ? 14 : height >= 32 ? 18 : 16;
  const iconY = Math.round((height - iconSize) / 2);
  const textY = Math.round(height / 2 + fontSize / 2 - 1.5);
  const safeValue = escapeXml(value);
  const safeLabel = label ? escapeXml(label) : "";
  const titleText = ariaLabel ?? (label ? `${label}: ${value}` : value);
  const safeTitle = escapeXml(titleText);
  if (style === "solid") {
    const isBrightBg = isBrightColor(color);
    const resolvedTextColor = getOptimalForeground(color, textColor, autoContrast);
    const resolvedIconColor = getOptimalForeground(color, iconColor, autoContrast);
    const padLeft2 = iconPath ? 10 : 12;
    const padRight2 = 12;
    const iconGap2 = iconPath ? 7 : 0;
    const iconTotal2 = iconPath ? iconSize + iconGap2 : 0;
    const textWidth2 = measureText(value, fontSize, true, letterSpacing);
    const totalWidth2 = padLeft2 + iconTotal2 + textWidth2 + padRight2;
    const iconX2 = padLeft2;
    const textX2 = padLeft2 + iconTotal2;
    const iconSvg2 = iconPath ? `  <svg x="${iconX2}" y="${iconY}" width="${iconSize}" height="${iconSize}" viewBox="${iconViewBox}" aria-hidden="true">
    <path fill="${resolvedIconColor}" d="${iconPath}"/>
  </svg>
` : "";
    const borderSvg = isBrightBg ? `  <rect width="${totalWidth2}" height="${height}" rx="${rx}" fill="none" stroke="rgba(0,0,0,0.12)" stroke-width="1"/>
` : "";
    return `<svg xmlns="http://www.w3.org/2000/svg" width="${totalWidth2}" height="${height}" viewBox="0 0 ${totalWidth2} ${height}" fill="none" role="img" aria-label="${safeTitle}">
  <title>${safeTitle}</title>
  <rect width="${totalWidth2}" height="${height}" rx="${rx}" fill="${color}"/>
${iconSvg2}  <text x="${textX2}" y="${textY}" fill="${resolvedTextColor}" font-family="${DEFAULT_FONT_FAMILY}" font-size="${fontSize}" font-weight="700" letter-spacing="${letterSpacing}px">${safeValue}</text>
${borderSvg}</svg>
`;
  }
  if (style === "split") {
    const isBrightLeft = isBrightColor(leftColor);
    const resolvedIconColor = getOptimalForeground(leftColor, iconColor, autoContrast);
    const resolvedLabelColor = labelColor ?? (isBrightLeft ? "#18181b" : PALETTE.lightGray);
    const resolvedValueColor = getOptimalForeground(color, textColor, autoContrast);
    const padLeft2 = iconPath ? 10 : 12;
    const iconGap2 = iconPath ? 7 : 0;
    const iconTotal2 = iconPath ? iconSize + iconGap2 : 0;
    const effectiveLabel = label || "status";
    const labelWidth = measureText(effectiveLabel, labelFontSize, false, letterSpacing);
    const leftPadInner = 10;
    const leftWidth = padLeft2 + iconTotal2 + labelWidth + leftPadInner;
    const valueWidth = measureText(value, fontSize, true, letterSpacing);
    const rightPadInner = 10;
    const rightPadOuter = 12;
    const rightWidth = rightPadInner + valueWidth + rightPadOuter;
    const totalWidth2 = leftWidth + rightWidth;
    const valueCenterX = Math.round(leftWidth + rightWidth / 2);
    const iconX2 = padLeft2;
    const labelX = padLeft2 + iconTotal2;
    const clipId = `clip_${Math.random().toString(36).substring(2, 8)}`;
    const iconSvg2 = iconPath ? `    <svg x="${iconX2}" y="${iconY}" width="${iconSize}" height="${iconSize}" viewBox="${iconViewBox}" aria-hidden="true">
      <path fill="${resolvedIconColor}" d="${iconPath}"/>
    </svg>
` : "";
    return `<svg xmlns="http://www.w3.org/2000/svg" width="${totalWidth2}" height="${height}" viewBox="0 0 ${totalWidth2} ${height}" fill="none" role="img" aria-label="${safeTitle}">
  <title>${safeTitle}</title>
  <clipPath id="${clipId}"><rect width="${totalWidth2}" height="${height}" rx="${rx}"/></clipPath>
  <g clip-path="url(#${clipId})">
    <rect width="${leftWidth}" height="${height}" fill="${leftColor}"/>
${iconSvg2}    <text x="${labelX}" y="${textY}" fill="${resolvedLabelColor}" font-family="${DEFAULT_FONT_FAMILY}" font-size="${labelFontSize}" font-weight="500" letter-spacing="${letterSpacing}px">${safeLabel || effectiveLabel}</text>
    <rect x="${leftWidth}" width="${rightWidth}" height="${height}" fill="${color}"/>
    <text x="${valueCenterX}" y="${textY}" fill="${resolvedValueColor}" font-family="${DEFAULT_FONT_FAMILY}" font-size="${fontSize}" font-weight="700" text-anchor="middle" letter-spacing="${letterSpacing}px">${safeValue}</text>
  </g>
  <rect width="${totalWidth2}" height="${height}" rx="${rx}" fill="none" stroke="${PALETTE.slateBorder}" stroke-width="1"/>
</svg>
`;
  }
  const padLeft = iconPath ? 10 : 12;
  const padRight = 12;
  const iconGap = iconPath ? 7 : 0;
  const iconTotal = iconPath ? iconSize + iconGap : 0;
  const fullText = label ? `${label} ${value}` : value;
  const textWidth = measureText(fullText, fontSize, true, letterSpacing);
  const totalWidth = padLeft + iconTotal + textWidth + padRight;
  const iconX = padLeft;
  const textX = padLeft + iconTotal;
  const iconSvg = iconPath ? `  <svg x="${iconX}" y="${iconY}" width="${iconSize}" height="${iconSize}" viewBox="${iconViewBox}" aria-hidden="true">
    <path fill="${color}" d="${iconPath}"/>
  </svg>
` : "";
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${totalWidth}" height="${height}" viewBox="0 0 ${totalWidth} ${height}" fill="none" role="img" aria-label="${safeTitle}">
  <title>${safeTitle}</title>
  <rect x="0.5" y="0.5" width="${totalWidth - 1}" height="${height - 1}" rx="${rx}" fill="${PALETTE.slateDeep}" stroke="${color}" stroke-width="1"/>
${iconSvg}  <text x="${textX}" y="${textY}" fill="${color}" font-family="${DEFAULT_FONT_FAMILY}" font-size="${fontSize}" font-weight="700" letter-spacing="${letterSpacing}px">${escapeXml(fullText)}</text>
</svg>
`;
}

