function getPreset(id) {
  return PRESETS[id.toLowerCase()];
}
function listPresets() {
  return Object.values(PRESETS);
}

// src/index.ts
function badgeFromPreset(presetId, overrides = {}) {
  const preset = getPreset(presetId);
  if (!preset) {
    throw new Error(`Preset "${presetId}" not found. Run badgify list to see available presets.`);
  }
  return generateBadge({
    value: preset.value,
    label: preset.label,
    color: preset.color,
    icon: preset.icon,
    style: preset.defaultStyle,
    ...overrides
  });
}
